     1	package rabinkarp;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	public final class RabinKarpMatcher implements StringMatcher {
     7	    public static final int DEFAULT_RADIX = 256;
     8	    public static final int DEFAULT_MODULUS = 101;
     9	
    10	    private final int radix;
    11	    private final int modulus;
    12	
    13	    public RabinKarpMatcher(int radix, int modulus) {
    14	        this.radix = radix;
    15	        this.modulus = modulus;
    16	    }
    17	
    18	    @Override
    19	    public List<Integer> search(CharSequence pattern, CharSequence text) {
    20	        CompiledPattern cp = CompiledPattern.compile(pattern, radix, modulus);
    21	        int n = text.length();
    22	        int m = cp.length();
    23	        int txtHash = hashOf(text, m);
    24	        List<Integer> result = allMatchPositions(n - m + 1);
    25	        for (int i = 0; i <= n - m; i++) {
    26	            if (cp.hash() == txtHash && matchesAt(text, cp.pattern(), i)) {
    27	                result.add(i);
    28	            }
    29	            if (i < n - m) {
    30	                txtHash = rollHash(txtHash, text.charAt(i), text.charAt(i + m), cp.highOrderFactor());
    31	            }
    32	        }
    33	        return result;
    34	    }
    35	
    36	    List<Integer> search(RabinKarpPattern pattern, CharSequence text) {
    37	        int n = text.length();
    38	        int m = pattern.length();
    39	        int txtHash = hashOf(text, m);
    40	        List<Integer> result = allMatchPositions(n - m + 1);
    41	        for (int i = 0; i <= n - m; i++) {
    42	            if (pattern.hash() == txtHash && matchesAt(text, pattern.pattern(), i)) {
    43	                result.add(i);
    44	            }
    45	            if (i < n - m) {
    46	                txtHash = rollHash(txtHash, text.charAt(i), text.charAt(i + m), pattern.highOrderFactor());
    47	            }
    48	        }
    49	        return result;
    50	    }
    51	
    52	    private List<Integer> allMatchPositions(int initialCapacity) {
    53	        return new ArrayList<>(initialCapacity);
    54	    }
    55	
    56	    private int hashOf(CharSequence seq, int length) {
    57	        int hash = 0;
    58	        for (int i = 0; i < length; i++) {
    59	            hash = (radix * hash + seq.charAt(i)) % modulus;
    60	        }
    61	        return hash;
    62	    }
    63	
    64	    private boolean matchesAt(CharSequence text, CharSequence pattern, int pos) {
    65	        for (int j = 0; j < pattern.length(); j++) {
    66	            if (text.charAt(pos + j) != pattern.charAt(j)) return false;
    67	        }
    68	        return true;
    69	    }
    70	
    71	    private int rollHash(int currentHash, char leaving, char entering, int highOrderFactor) {
    72	        int hash = (radix * (currentHash - leaving * highOrderFactor) + entering) % modulus;
    73	        if (hash < 0) hash += modulus;
    74	        return hash;
    75	    }
    76	}

